import {createLayoutModel} from './layout-state.mjs';
// Native Athena authoring module. Deliberately excludes artist provenance and account sessions.
export async function mount(context){
 const {container,signal,notify=()=>{}}=context;const doc=container.ownerDocument;
 const response=await fetch(new URL('./catalog.json',import.meta.url),{signal});if(!response.ok)throw Error('Foundry catalog unavailable.');
 const {themes}=await response.json();if(signal.aborted)return {unmount(){}};
 const model=createLayoutModel(themes);let current=model.initial(),layouts={},query=String(context.search||''),disposed=false,drag=null,invalidSavedState=false,importGeneration=0;
 try{if(context.state!==undefined){const envelope=context.state;if(!envelope||envelope.version!==1||!envelope.active||!envelope.layouts||typeof envelope.layouts!=='object'||Array.isArray(envelope.layouts))throw Error('Unsupported saved envelope.');for(const [id,value] of Object.entries(envelope.layouts)){const checked=model.validate(value);if(id!==checked.roomId)throw Error('Layout key mismatch.');layouts[id]=checked;}current=model.validate(envelope.active);}}catch{invalidSavedState=true;notify('Saved Foundry data is invalid and will not be overwritten. Import a recovered layout to resume saving.');}
 const root=doc.createElement('section');root.className='foundry-workspace';root.dataset.theme=context.theme==='light'?'light':'dark';
 const css=doc.createElement('link');css.rel='stylesheet';css.href=new URL('./style.css',import.meta.url).href;container.append(css,root);
 root.innerHTML='<header><p class="eyebrow">NATIVE BUILD WORKSPACE · LAYOUT AUTHORING</p><h1>Shape a living workspace</h1><p>17 source themes, 34 rooms and all 85 ecology objects. Arrange, pin and preserve room layouts inside Athena.</p></header><p class="foundry-boundary">This authoring phase is not full Living World parity. Original 3D rendering, animated mascots, artist worlds, native SQLite and provider account controls remain pending. No media autoplay or account requests.</p><div class="foundry-toolbar"><label>Theme <select data-theme-select></select></label><label>Room <select data-room-select></select></label><label>Time <select data-time><option value="dawn">dawn</option><option value="day">day</option><option value="dusk">dusk</option><option value="night">night</option></select></label><button type="button" data-export>Export this layout</button><label class="foundry-import">Import layout<input type="file" accept="application/json,.json" data-import></label></div><p class="foundry-status" role="status" aria-live="polite"></p><div class="foundry-grid"><div class="foundry-scene" role="group" aria-label="Room layout. Tab to objects; arrow keys move, P pins or unpins."></div><aside><h2>Object ecology</h2><p>Drag or use arrow keys to position. Press P to pin. Positions are normalized to the room.</p><ul class="foundry-objects"></ul></aside></div>';
 const one=s=>root.querySelector(s),themeSelect=one('[data-theme-select]'),roomSelect=one('[data-room-select]'),timeSelect=one('[data-time]'),scene=one('.foundry-scene'),list=one('.foundry-objects'),status=one('.foundry-status');
 for(const t of themes){const o=doc.createElement('option');o.value=t.id;o.textContent=t.name;themeSelect.append(o);}
 const text=s=>{status.textContent=s;};
 const snapshot=()=>{if(invalidSavedState)throw Error('Invalid existing state is retained for recovery.');return {version:1,active:model.validate(current),layouts:Object.fromEntries(Object.entries(layouts).map(([k,v])=>[k,model.validate(v)]))};};
 function save(){layouts[current.roomId]=model.validate(current);try{context.setState?.(snapshot());text('Layout updated. Athena reports storage failures separately; export a backup for recovery.');}catch{ text('Could not save this layout. Export a backup before leaving.');}}
 const pos=(id,i)=>current.placements[id]||{x:.15+(i%3)*.32,y:.25+Math.floor(i/3)*.4,pinned:false};
 function position(button,p){button.style.left=`${p.x*100}%`;button.style.top=`${p.y*100}%`;button.setAttribute('aria-pressed',String(p.pinned));}
 function draw(){
  const t=themes.find(t=>t.id===current.themeId);themeSelect.value=t.id;roomSelect.replaceChildren();for(const r of t.rooms){const o=doc.createElement('option');o.value=r.id;o.textContent=r.name;roomSelect.append(o);}roomSelect.value=current.roomId;timeSelect.value=current.time;scene.dataset.time=current.time;scene.replaceChildren();list.replaceChildren();
  let visible=0;
  t.objects.forEach((o,i)=>{if(query&&!`${t.name} ${o.name} ${o.shape} ${o.role}`.toLowerCase().includes(query.toLowerCase()))return;visible++;
   const b=doc.createElement('button');b.type='button';b.className='foundry-object';b.dataset.id=o.id;b.textContent=o.name;b.title=`${o.shape} · ${o.role}`;b.setAttribute('aria-label',`${o.name}; arrow keys move; P toggles pin`);position(b,pos(o.id,i));scene.append(b);
   const li=doc.createElement('li');li.textContent=`${o.name} · ${o.shape} · ${o.role}`;list.append(li);
  });text(`${visible} of ${t.objects.length} objects visible in ${t.rooms.find(r=>r.id===current.roomId).name}.`);
 }
 function switchRoom(themeId,roomId){importGeneration++;layouts[current.roomId]=model.validate(current);current=layouts[roomId]?model.validate(layouts[roomId]):{...model.initial(themeId),roomId};draw();save();}
 const onTheme=()=>{const t=themes.find(t=>t.id===themeSelect.value);switchRoom(t.id,t.rooms[0].id);};const onRoom=()=>switchRoom(current.themeId,roomSelect.value);const onTime=()=>{importGeneration++;current.time=timeSelect.value;scene.dataset.time=current.time;save();};
 themeSelect.addEventListener('change',onTheme);roomSelect.addEventListener('change',onRoom);timeSelect.addEventListener('change',onTime);
 function update(id,change){importGeneration++;const t=themes.find(t=>t.id===current.themeId),i=t.objects.findIndex(o=>o.id===id);if(i<0)return;const old=pos(id,i);current.placements[id]={...old,...change};const b=Array.from(scene.children).find(b=>b.dataset.id===id);if(b)position(b,current.placements[id]);save();}
 const down=e=>{const b=e.target.closest?.('[data-id]');if(!b||!scene.contains(b)||e.button!==0)return;const t=themes.find(t=>t.id===current.themeId),p=pos(b.dataset.id,t.objects.findIndex(o=>o.id===b.dataset.id));if(p.pinned){text('Object is pinned. Press P to unpin.');return;}drag={id:b.dataset.id,pointer:e.pointerId,button:b};b.setPointerCapture?.(e.pointerId);};
 const move=e=>{if(!drag||drag.pointer!==e.pointerId)return;const box=scene.getBoundingClientRect();if(box.width&&box.height)update(drag.id,{x:Math.min(.94,Math.max(.06,(e.clientX-box.left)/box.width)),y:Math.min(.94,Math.max(.06,(e.clientY-box.top)/box.height))});};
 const up=()=>{drag=null;};
 const key=e=>{const b=e.target.closest?.('[data-id]');if(!b||!scene.contains(b))return;const t=themes.find(t=>t.id===current.themeId),p=pos(b.dataset.id,t.objects.findIndex(o=>o.id===b.dataset.id));if(e.key.toLowerCase()==='p'){e.preventDefault();update(b.dataset.id,{pinned:!p.pinned});return;}const delta={ArrowLeft:[-.02,0],ArrowRight:[.02,0],ArrowUp:[0,-.02],ArrowDown:[0,.02]}[e.key];if(!delta)return;e.preventDefault();if(p.pinned){text('Object is pinned. Press P to unpin.');return;}update(b.dataset.id,{x:Math.min(.94,Math.max(.06,p.x+delta[0])),y:Math.min(.94,Math.max(.06,p.y+delta[1]))});};
 scene.addEventListener('pointerdown',down);scene.addEventListener('pointermove',move);scene.addEventListener('pointerup',up);scene.addEventListener('pointercancel',up);scene.addEventListener('keydown',key);
 let objectUrl=null;const exportButton=one('[data-export]'),importInput=one('[data-import]');
 const download=()=>{if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl=URL.createObjectURL(new Blob([model.encode(current)],{type:'application/json'}));const a=doc.createElement('a');a.href=objectUrl;a.download='athena-room-layout.json';a.click();};
 const upload=async()=>{const generation=++importGeneration;const file=importInput.files?.[0];if(!file)return;try{if(file.size>200000)throw Error('Layout exceeds import limit.');const value=model.parse(await file.text());if(disposed||signal.aborted||generation!==importGeneration)return;layouts[current.roomId]=model.validate(current);current=value;invalidSavedState=false;draw();save();text('Validated room layout imported. Other rooms were preserved.');}catch(e){if(!disposed&&generation===importGeneration)text(`Import not applied: ${e.message}`);}finally{if(!disposed&&generation===importGeneration)importInput.value='';}};
 exportButton.addEventListener('click',download);importInput.addEventListener('change',upload);draw();
 function unmount(){if(disposed)return;disposed=true;drag=null;if(objectUrl)URL.revokeObjectURL(objectUrl);root.remove();css.remove();signal.removeEventListener('abort',unmount);}
 signal.addEventListener('abort',unmount,{once:true});
 return {unmount,exportState:snapshot,setSearch(q){query=String(q||'');drag=null;draw();},setTheme(t){root.dataset.theme=t==='light'?'light':'dark';}};
}
